export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

const relativeAutoFormatter = new Intl.RelativeTimeFormat("en", { numeric: "auto" })
const relativeAlwaysFormatter = new Intl.RelativeTimeFormat("en", { numeric: "always" })

const timeFormatter = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const dateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const dateWithYearFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })
const longDateFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const longDateWithYearFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })
const shortDateTimeFormatter = new Intl.DateTimeFormat("en-US", { dateStyle: "short", timeStyle: "short" })
const fullDateTimeFormatter = new Intl.DateTimeFormat("en-US", { dateStyle: "full", timeStyle: "short" })

export function formatTime(date) {
  return timeFormatter.format(date)
}

export function formatDate(date, now = new Date()) {
  if (date.getFullYear() === now.getFullYear()) {
    return dateFormatter.format(date)
  } else {
    return dateWithYearFormatter.format(date)
  }
}

export function formatStamp(date) {
  return dateWithYearFormatter.format(date)
}

export function formatLongDate(date, now = new Date()) {
  if (date.getFullYear() === now.getFullYear()) {
    return longDateFormatter.format(date)
  } else {
    return longDateWithYearFormatter.format(date)
  }
}

export function formatDateTime(date) {
  return shortDateTimeFormatter.format(date)
}

export function formatFull(date) {
  return fullDateTimeFormatter.format(date)
}

// Smart format for comments and similar: same day as clock time,
// yesterday/tomorrow as words, within a week as relative days,
// older as calendar date.
export function formatSmart(date, now = new Date()) {
  const diffDays = signedDifferenceInDays(now, date)

  if (diffDays === 0) {
    return formatTime(date)
  } else if (Math.abs(diffDays) < 7) {
    return relativeAutoFormatter.format(diffDays, "day")
  } else {
    return formatDate(date, now)
  }
}

// Future-oriented format for auto-close notices: today/tomorrow as words,
// further out as "in 3 days", "in 2 months", etc.
export function formatFuture(date, now = new Date()) {
  const diffDays = signedDifferenceInDays(now, date)

  if (diffDays === 0) {
    return relativeAutoFormatter.format(0, "day")
  } else if (Math.abs(diffDays) < 30) {
    return relativeAutoFormatter.format(diffDays, "day")
  } else {
    return formatRelative(date, now)
  }
}

// Always-relative format like "5 days ago", "2 hours ago", "in 3 days".
export function formatRelative(date, now = new Date()) {
  const diffSeconds = Math.round((date - now) / 1000)
  const absSeconds = Math.abs(diffSeconds)

  if (absSeconds < 60) {
    if (diffSeconds === 0) return "just now"
    return relativeAlwaysFormatter.format(diffSeconds, "second")
  }

  const diffMinutes = Math.round(diffSeconds / 60)
  const absMinutes = Math.abs(diffMinutes)
  if (absMinutes < 60) {
    return relativeAlwaysFormatter.format(diffMinutes, "minute")
  }

  const diffHours = Math.round(diffMinutes / 60)
  const absHours = Math.abs(diffHours)
  if (absHours < 24) {
    return relativeAlwaysFormatter.format(diffHours, "hour")
  }

  const diffDays = signedDifferenceInDays(now, date)
  const absDays = Math.abs(diffDays)
  if (absDays < 30) {
    return relativeAutoFormatter.format(diffDays, "day")
  }

  const diffMonths = monthDifference(now, date)
  const absMonths = Math.abs(diffMonths)
  if (absMonths < 12) {
    return relativeAlwaysFormatter.format(diffMonths, "month")
  }

  const diffYears = Math.round(diffMonths / 12)
  return relativeAlwaysFormatter.format(diffYears, "year")
}

export function formatByName(date, format, now = new Date()) {
  switch ((format || "smart").toString()) {
    case "smart":
    case "comment":
      return formatSmart(date, now)
    case "relative":
    case "ago":
      return formatRelative(date, now)
    case "future":
    case "entropy":
      return formatFuture(date, now)
    case "date":
    case "calendar":
      return formatDate(date, now)
    case "stamp":
    case "date_with_year":
    case "date-with-year":
      return formatStamp(date)
    case "time":
    case "clock":
      return formatTime(date)
    case "datetime":
    case "date_time":
    case "short":
      return formatDateTime(date)
    case "long_date":
    case "long-date":
    case "long":
    case "full_date":
      return formatLongDate(date, now)
    case "full":
      return formatFull(date)
    default:
      return formatSmart(date, now)
  }
}

function monthDifference(fromDate, toDate) {
  const months = (toDate.getFullYear() - fromDate.getFullYear()) * 12 + (toDate.getMonth() - fromDate.getMonth())
  // Adjust when the day hasn't been reached yet in the target month
  if (months > 0 && toDate.getDate() < fromDate.getDate()) return months - 1
  if (months < 0 && toDate.getDate() > fromDate.getDate()) return months + 1
  return months
}
