<script>
#{js}

function runTests() {
  const results = [];
  function check(name, actual, expected) {
    const pass = actual === expected;
    results.push(`${pass ? "PASS" : "FAIL"}: ${name} => "${actual}" (expected "${expected}")`);
  }
  function checkPattern(name, actual, pattern) {
    const pass = pattern.test(actual);
    results.push(`${pass ? "PASS" : "FAIL"}: ${name} => "${actual}" (expected ${pattern})`);
  }

  const now = new Date(2025, 8, 12, 15, 0, 0); // Sep 12, 2025 3PM

  // Relative minutes/hours
  check("relative 5 min ago", formatRelative(new Date(2025,8,12,14,55,0), now), "5 minutes ago");
  check("relative in 5 min", formatRelative(new Date(2025,8,12,15,5,0), now), "in 5 minutes");
  check("relative 2 hours ago", formatRelative(new Date(2025,8,12,13,0,0), now), "2 hours ago");
  check("relative in 2 hours", formatRelative(new Date(2025,8,12,17,0,0), now), "in 2 hours");
  check("relative 1 min ago", formatRelative(new Date(2025,8,12,14,59,0), now), "1 minute ago");
  check("relative 1 hour ago", formatRelative(new Date(2025,8,12,14,0,0), now), "1 hour ago");

  // Relative days with auto (yesterday/tomorrow)
  check("relative yesterday", formatRelative(new Date(2025,8,11,10,0,0), now), "yesterday");
  check("relative tomorrow", formatRelative(new Date(2025,8,13,10,0,0), now), "tomorrow");

  // Future
  check("future today", formatFuture(new Date(2025,8,12,18,0,0), now), "today");
  check("future tomorrow", formatFuture(new Date(2025,8,13,9,0,0), now), "tomorrow");
  check("future in 3 days", formatFuture(new Date(2025,8,15,9,0,0), now), "in 3 days");

  // Date with year logic
  check("date same year", formatDate(new Date(2025,8,10,12,0,0), now), "Sep 10");
  check("date diff year", formatDate(new Date(2024,8,10,12,0,0), now), "Sep 10, 2024");
  check("stamp", formatStamp(new Date(2025,8,12,12,0,0)), "Sep 12, 2025");
  check("long same year", formatLongDate(new Date(2025,8,12,12,0,0), now), "Friday, September 12");
  checkPattern("long diff year", formatLongDate(new Date(2024,8,12,12,0,0), now), /2024/);

  // Time
  check("time 1:42 PM", formatTime(new Date(2025,8,12,13,42,0)), "1:42 PM");
  check("time 9:05 AM", formatTime(new Date(2025,8,12,9,5,0)), "9:05 AM");

  // Datetime (access tokens)
  checkPattern("datetime", formatDateTime(new Date(2025,8,12,13,42,0)), /9\\/12\\/25.*1:42 PM/);

  // Smart old
  checkPattern("smart old", formatSmart(new Date(2025,7,1,12,0,0), now), /Aug 1|Jul/);

  // formatByName aliases
  check("byName time", formatByName(new Date(2025,8,12,13,42,0), "time", now), "1:42 PM");
  check("byName date", formatByName(new Date(2025,8,10,12,0,0), "date", now), "Sep 10");
  check("byName relative", formatByName(new Date(2025,8,7,12,0,0), "relative", now), "5 days ago");

  document.getElementById("results").textContent = results.join("\\n");
}
runTests();
</script>
</body></html>
